// frontend/src/utils/SiteImage.jsx
// ✅ v5 (Fixed — Size, Zoom Cap, Icon Safety):
//
//  🐛 FIXES نسبت به v4:
//  ۱. باگ اصلی: `height: 'auto'` inline روی هر عکسی با کلاس h-X اعمال می‌شد
//     و کلاس h-X (مثل h-20 در کارت مواد اولیه) رو نابود می‌کرد. حالا اگه
//     className صراحتاً h-* یا w-* داشته باشه، width/height inline اصلاً
//     اعمال نمی‌شه — CSS کنترل می‌کنه.
//  ۲. zoom از دیتابیس حالا بین 50 تا 150 درصد clamp می‌شه. قبلاً اگه DB
//     مقدار 500 داشت، عکس ۵ برابر بزرگ می‌شد.
//  ۳. در icon-mode، objectFit/objectPosition/zoom از دیتابیس نادیده گرفته
//     می‌شه و همیشه `contain` + `center` استفاده می‌شه. قبلاً `cover` از DB
//     روی `contain` رو override می‌کرد و آیکون‌ها کراپ می‌شدن.
//  ۴. prop جدید `maxHeight` (پیش‌فرض `70vh`) — برای کارت‌های مواد اولیه
//     می‌تونی `maxHeight="8rem"` پاس بدی تا عکس بدون کلاس سایز، بزرگ نشه.
//  ۵. در همه شاخه‌ها، `width: auto` هم برای عکس بدون سایز اضافه شد.
// ============================================================
import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { API_BASE } from '../config/api';

const CACHE_TTL = 5 * 60 * 1000; // 5 minutes

const DEFAULT_IMAGE_SETTINGS = {
  objectFit: 'cover',
  zoom: 100,
  posX: 50,
  posY: 50,
};

// ✅ FIX v5: سقف و کف zoom — جلوگیری از scale های عجیب
const ZOOM_MIN = 50;
const ZOOM_MAX = 150;

const DEFAULT_PLACEHOLDER_CLASS = 'bg-paper-100 dark:bg-ink-700 text-ink-400';

const imageCache = new Map();
const pendingRequests = new Map();

// ============================================================
//  🔄 Version counter — برای force re-render کامپوننت‌ها
// ============================================================
let globalVersion = 0;
const versionListeners = new Set();

function bumpVersion() {
  globalVersion++;
  versionListeners.forEach((listener) => listener(globalVersion));
}

function useCacheVersion() {
  const [version, setVersion] = useState(globalVersion);
  useEffect(() => {
    versionListeners.add(setVersion);
    return () => versionListeners.delete(setVersion);
  }, []);
  return version;
}

// ============================================================
//  📡 BroadcastChannel — cross-tab sync
// ============================================================
const BROADCAST_CHANNEL_NAME = 'miko_site_images_updates';
let broadcastChannel = null;

if (typeof window !== 'undefined' && 'BroadcastChannel' in window) {
  try {
    broadcastChannel = new BroadcastChannel(BROADCAST_CHANNEL_NAME);
    broadcastChannel.onmessage = (event) => {
      if (event.data?.type === 'invalidate') {
        const key = event.data.key;
        if (key) imageCache.delete(key);
        else imageCache.clear();
        bumpVersion();
      }
    };
  } catch (err) {
    console.warn('BroadcastChannel init failed:', err);
  }
}

// ============================================================
//  👁️ Visibility/focus — invalidate وقتی کاربر برمی‌گرده
// ============================================================
if (typeof window !== 'undefined') {
  let lastInvalidation = 0;
  const MIN_INTERVAL = 3000;

  const handler = () => {
    if (document.visibilityState !== 'visible') return;
    const now = Date.now();
    if (now - lastInvalidation < MIN_INTERVAL) return;
    lastInvalidation = now;
    imageCache.clear();
    bumpVersion();
  };

  document.addEventListener('visibilitychange', handler);
  window.addEventListener('focus', handler);
}

// ============================================================
//  ⏰ Watchdog — TTL رو واقعاً اجرا کن
// ============================================================
if (typeof window !== 'undefined') {
  setInterval(() => {
    const now = Date.now();
    let changed = false;
    for (const [key, entry] of imageCache.entries()) {
      if (now - entry.timestamp > CACHE_TTL) {
        imageCache.delete(key);
        changed = true;
      }
    }
    if (changed) bumpVersion();
  }, 60000);
}

// ============================================================
//  Cache helpers
// ============================================================
function getFromCache(key) {
  const entry = imageCache.get(key);
  if (!entry) return null;
  if (Date.now() - entry.timestamp > CACHE_TTL) {
    imageCache.delete(key);
    return null;
  }
  return entry;
}

function setInCache(key, raw) {
  if (!raw || (!raw.url && !raw.fallback)) return;
  const hasUrl = !!raw.url;
  const fullUrl = hasUrl
    ? raw.url.startsWith('http')
      ? raw.url
      : `${API_BASE}${raw.url}`
    : null;
  imageCache.set(key, {
    data: {
      url: raw.url || '',
      fallback: raw.fallback || '',
      objectFit:
        raw.object_fit ?? raw.objectFit ?? DEFAULT_IMAGE_SETTINGS.objectFit,
      zoom: raw.zoom ?? DEFAULT_IMAGE_SETTINGS.zoom,
      posX: raw.pos_x ?? raw.posX ?? DEFAULT_IMAGE_SETTINGS.posX,
      posY: raw.pos_y ?? raw.posY ?? DEFAULT_IMAGE_SETTINGS.posY,
    },
    fullUrl,
    timestamp: Date.now(),
  });
}

function invalidateCache(key = null, broadcast = true) {
  if (key === null) imageCache.clear();
  else imageCache.delete(key);
  bumpVersion();

  if (broadcast && broadcastChannel) {
    try {
      broadcastChannel.postMessage({ type: 'invalidate', key });
    } catch {
      /* silent */
    }
  }
}

// ============================================================
//  Fetch
// ============================================================
async function fetchImageData(key) {
  const normalizedKey = (key || '')
    .trim()
    .toLowerCase()
    .replace(/\s+/g, '_')
    .replace(/-/g, '_');

  if (!normalizedKey) return null;

  const cached = getFromCache(normalizedKey);
  if (cached) return cached;

  if (pendingRequests.has(normalizedKey))
    return pendingRequests.get(normalizedKey);

  const promise = axios
    .get(`${API_BASE}/api/site-images/${normalizedKey}`)
    .then((res) => {
      const data = res.data;
      if (!data || (!data.url && !data.fallback)) return null;
      setInCache(normalizedKey, data);
      return getFromCache(normalizedKey);
    })
    .catch((err) => {
      if (err.response?.status === 404) return null;
      console.warn(`خطا در گرفتن عکس '${normalizedKey}':`, err);
      return null;
    })
    .finally(() => {
      pendingRequests.delete(normalizedKey);
    });

  pendingRequests.set(normalizedKey, promise);
  return promise;
}

function fetchImage(key) {
  return fetchImageData(key).then((entry) => entry?.fullUrl || null);
}

function isUrlLike(str) {
  if (!str) return false;
  return /^(https?:|\/|data:)/.test(String(str));
}

// ============================================================
//  Hook: useSiteImage
// ============================================================
export function useSiteImage(key) {
  const version = useCacheVersion();
  const [state, setState] = useState({
    url: null,
    fullUrl: null,
    fallback: '',
    ...DEFAULT_IMAGE_SETTINGS,
    loading: true,
    error: null,
  });

  useEffect(() => {
    if (!key) {
      setState({
        url: null,
        fullUrl: null,
        fallback: '',
        ...DEFAULT_IMAGE_SETTINGS,
        loading: false,
        error: null,
      });
      return;
    }

    let cancelled = false;
    setState((prev) => ({ ...prev, loading: true }));

    fetchImageData(key)
      .then((entry) => {
        if (cancelled) return;
        if (!entry) {
          setState({
            url: null,
            fullUrl: null,
            fallback: '',
            ...DEFAULT_IMAGE_SETTINGS,
            loading: false,
            error: null,
          });
          return;
        }
        setState({
          url: entry.fullUrl,
          fullUrl: entry.fullUrl,
          fallback: entry.data.fallback || '',
          objectFit: entry.data.objectFit,
          zoom: entry.data.zoom,
          posX: entry.data.posX,
          posY: entry.data.posY,
          loading: false,
          error: null,
        });
      })
      .catch((err) => {
        if (cancelled) return;
        setState({
          url: null,
          fullUrl: null,
          fallback: '',
          ...DEFAULT_IMAGE_SETTINGS,
          loading: false,
          error: err,
        });
      });

    return () => {
      cancelled = true;
    };
  }, [key, version]);

  return state;
}

// ============================================================
//  Hook: useSiteImages (batch)
// ============================================================
export function useSiteImages(keys) {
  const version = useCacheVersion();
  const [state, setState] = useState({ images: {}, loading: true });

  useEffect(() => {
    if (!keys || !Array.isArray(keys) || keys.length === 0) {
      setState({ images: {}, loading: false });
      return;
    }

    let cancelled = false;
    setState((prev) => ({ ...prev, loading: true }));

    axios
      .get(`${API_BASE}/api/site-images/batch`, {
        params: { keys: keys.join(',') },
      })
      .then((res) => {
        if (cancelled) return;
        const imagesMap = res.data?.images || {};
        const processed = {};
        for (const [k, v] of Object.entries(imagesMap)) {
          if (v?.url) {
            const fullUrl = v.url.startsWith('http')
              ? v.url
              : `${API_BASE}${v.url}`;
            processed[k] = {
              url: fullUrl,
              fullUrl,
              objectFit:
                v.object_fit ?? v.objectFit ?? DEFAULT_IMAGE_SETTINGS.objectFit,
              zoom: v.zoom ?? DEFAULT_IMAGE_SETTINGS.zoom,
              posX: v.pos_x ?? v.posX ?? DEFAULT_IMAGE_SETTINGS.posX,
              posY: v.pos_y ?? v.posY ?? DEFAULT_IMAGE_SETTINGS.posY,
            };
            setInCache(k, v);
          }
        }
        setState({ images: processed, loading: false });
      })
      .catch((err) => {
        if (cancelled) return;
        console.warn('خطا در گرفتن عکس‌ها (batch):', err);
        setState({ images: {}, loading: false });
      });

    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [keys?.join(','), version]);

  return state;
}

// ============================================================
//  ✅ FIX v3: تشخیص آیکون — فقط اگه className هم w-X و هم h-X
//  داشته باشه، و اون X ها کوچیک باشن (<=12 در tailwind).
// ============================================================
function looksLikeIconClass(className) {
  if (!className) return false;

  // اگه w-full یا h-full داره، قطعاً عکس بزرگه
  if (className.includes('w-full') || className.includes('h-full')) return false;

  const wMatch = className.match(/\bw-(\d+)\b/);
  const hMatch = className.match(/\bh-(\d+)\b/);

  // اگه هیچ‌کدوم نبودن، تشخیص از روی text- (مثل text-3xl)
  if (!wMatch || !hMatch) {
    return (
      className.includes('text-') &&
      !className.includes('w-') &&
      !className.includes('h-')
    );
  }

  // اگه هر دو هستن، فقط اگه کوچیک باشن (<=12 → ~3rem) آیکونه
  const wSize = parseInt(wMatch[1], 10);
  const hSize = parseInt(hMatch[1], 10);
  return wSize <= 12 && hSize <= 12;
}

// ============================================================
//  ✅ FIX v3: تشخیص اندازه‌ی صریح
// ============================================================
function hasExplicitSize(className) {
  if (!className) return false;
  return (
    /\bw-(\d+|full|auto|screen|px|1\/\d+)\b/.test(className) ||
    /\bh-(\d+|full|auto|screen|px|1\/\d+)\b/.test(className) ||
    /\bmax-w-/.test(className) ||
    /\bmax-h-/.test(className) ||
    /\baspect-/.test(className)
  );
}

// ✅ FIX v5: بررسی صریح عرض و ارتفاع جداگانه
function hasExplicitWidth(className) {
  if (!className) return false;
  return /\bw-(\d+|full|auto|screen|px|1\/\d+)\b/.test(className);
}

function hasExplicitHeight(className) {
  if (!className) return false;
  return /\bh-(\d+|full|auto|screen|px|1\/\d+)\b/.test(className);
}

// ============================================================
//  ✅ FIX v4: تشخیص نهایی icon-mode
// ============================================================
function resolveIsIconMode(isIconProp, className) {
  if (isIconProp === true) return true;
  if (isIconProp === false) return false;
  return looksLikeIconClass(className);
}

// ============================================================
//  ✅ FIX v5: clamp zoom
// ============================================================
function clampZoom(value) {
  const n = Number(value);
  if (!Number.isFinite(n) || n <= 0) return 100;
  return Math.max(ZOOM_MIN, Math.min(ZOOM_MAX, n));
}

// ============================================================
//  کامپوننت SiteImage
// ============================================================
export function SiteImage({
  imageKey,
  fallback = null,
  alt = '',
  className = '',
  style = {},
  loadingClassName = '',
  showPlaceholder = false,
  placeholderContent = null,
  placeholderClassName = DEFAULT_PLACEHOLDER_CLASS,
  isIcon,
  onError = null,
  objectFit: objectFitProp,
  zoom: zoomProp,
  posX: posXProp,
  posY: posYProp,
  useImageSettings = true,
  maxHeight = '70vh', // ✅ FIX v5: prop جدید — قابل override توسط caller
  ...imgProps
}) {
  const {
    url,
    loading,
    fallback: dbFallback,
    objectFit,
    zoom,
    posX,
    posY,
  } = useSiteImage(imageKey);
  const finalFallback = fallback ?? dbFallback ?? null;

  // ✅ FIX v4: تشخیص نهایی icon-mode — یک‌بار برای همه شاخه‌ها
  const isIconMode = resolveIsIconMode(isIcon, className);

  // ============================================================
  //  ✅ FIX v5: computedStyle — zoom حالا clamp می‌شه
  // ============================================================
  const computedImgStyle = (() => {
    if (!useImageSettings) return { ...style };

    const finalObjectFit =
      objectFitProp ?? objectFit ?? DEFAULT_IMAGE_SETTINGS.objectFit;
    const finalZoom = clampZoom(
      zoomProp ?? zoom ?? DEFAULT_IMAGE_SETTINGS.zoom
    );
    const finalPosX = posXProp ?? posX ?? DEFAULT_IMAGE_SETTINGS.posX;
    const finalPosY = posYProp ?? posY ?? DEFAULT_IMAGE_SETTINGS.posY;

    const dynamic = {
      objectFit: finalObjectFit,
      objectPosition: `${finalPosX}% ${finalPosY}%`,
    };

    if (finalZoom !== 100) {
      dynamic.transform = `scale(${finalZoom / 100})`;
      dynamic.transformOrigin = `${finalPosX}% ${finalPosY}%`;
    }

    return { ...dynamic, ...style };
  })();

  // ============================================================
  //  ✅ FIX v5: استایل آیکون — همیشه contain/center
  //  بدون zoom / objectFit از DB تا آیکون کراپ یا بزرگ نشه
  // ============================================================
  const composeIconStyle = () => {
    const hasSizeClass = hasExplicitSize(className);
    return {
      objectFit: 'contain',
      objectPosition: 'center',
      flexShrink: 0,
      ...(hasSizeClass ? {} : { width: '1em', height: '1em' }),
      ...style,
    };
  };

  // ============================================================
  //  ✅ FIX v5: استایل عکس عادی
  //  اگه CSS سایز داره → فقط objectFit/zoom (width/height اصلاً override نمی‌شن)
  //  اگه نداره → max-safe defaults
  // ============================================================
  const composeNormalImgStyle = () => {
    const hasSize = hasExplicitSize(className);
    if (hasSize) {
      // احترام به CSS: width/height هیچ‌کدوم override نمی‌شن
      return { ...computedImgStyle };
    }
    // هیچ کلاس سایز نداریم — default امن
    return {
      maxWidth: '100%',
      maxHeight,
      width: 'auto',
      height: 'auto',
      ...computedImgStyle,
    };
  };

  // ============================================================
  //  Error handler مشترک
  // ============================================================
  const handleImgError = (e) => {
    if (finalFallback && isUrlLike(finalFallback)) {
      e.target.src = finalFallback;
    } else {
      e.target.style.display = 'none';
    }
    onError?.(e);
  };

  // ============================================================
  //  ✅ حالت loading
  // ============================================================
  if (loading) {
    if (isIconMode) {
      return (
        <span
          className={`${className} inline-flex items-center justify-center opacity-40 ${loadingClassName}`}
          style={style}
          aria-busy="true"
          aria-label="در حال بارگذاری آیکون..."
        >
          {finalFallback ? (
            <span className="leading-none select-none">{finalFallback}</span>
          ) : null}
        </span>
      );
    }

    if (placeholderContent) {
      return (
        <div
          className={`flex items-center justify-center ${placeholderClassName} ${className} ${loadingClassName}`}
          style={style}
          aria-busy="true"
          aria-label={alt || 'در حال بارگذاری عکس...'}
        >
          {placeholderContent}
        </div>
      );
    }

    return (
      <div
        className={`bg-paper-100 dark:bg-ink-700 animate-pulse ${className} ${loadingClassName}`}
        style={style}
        aria-busy="true"
        aria-label="در حال بارگذاری عکس..."
      />
    );
  }

  // ============================================================
  //  ✅ حالت URL موجود
  // ============================================================
  if (url) {
    // --- icon-mode ---
    if (isIconMode) {
      return (
        <img
          src={url}
          alt={alt}
          className={className}
          style={composeIconStyle()}
          loading="lazy"
          onError={handleImgError}
          {...imgProps}
        />
      );
    }

    // --- عکس عادی ---
    return (
      <img
        src={url}
        alt={alt}
        className={className}
        style={composeNormalImgStyle()}
        loading="lazy"
        onError={handleImgError}
        {...imgProps}
      />
    );
  }

  // ============================================================
  //  ✅ حالت placeholder (no URL, showPlaceholder=true)
  // ============================================================
  if (showPlaceholder) {
    return (
      <div
        className={`flex items-center justify-center ${placeholderClassName} ${className}`}
        style={style}
        aria-label={alt || 'عکس تنظیم نشده'}
      >
        {placeholderContent || (
          <span className="text-2xl opacity-60" aria-hidden="true">
            🖼️
          </span>
        )}
      </div>
    );
  }

  // ============================================================
  //  ✅ حالت fallback (no URL, showPlaceholder=false)
  // ============================================================
  if (finalFallback) {
    if (isUrlLike(finalFallback)) {
      // --- icon-mode fallback URL ---
      if (isIconMode) {
        return (
          <img
            src={finalFallback}
            alt={alt}
            className={className}
            style={composeIconStyle()}
            loading="lazy"
            {...imgProps}
          />
        );
      }
      // --- عکس عادی fallback URL ---
      return (
        <img
          src={finalFallback}
          alt={alt}
          className={className}
          style={composeNormalImgStyle()}
          loading="lazy"
          {...imgProps}
        />
      );
    }
    // fallback ایموجی
    return (
      <div
        className={`flex items-center justify-center ${className}`}
        style={style}
        aria-label={alt || String(finalFallback)}
      >
        <span className="leading-none select-none">{finalFallback}</span>
      </div>
    );
  }

  return null;
}

// ============================================================
//  Helper exports
// ============================================================
export function prefetchSiteImage(key) {
  return fetchImage(key);
}

export function prefetchSiteImages(keys) {
  if (!Array.isArray(keys)) return Promise.resolve();
  return Promise.all(keys.map((k) => fetchImage(k)));
}

export function invalidateSiteImageCache(key = null) {
  invalidateCache(key, true);
}

export default SiteImage;